(7566972, 1214173, 96751, '<td valign="top">I swear, this effect is so bizarre :)  Love the tiny people.</td>', 'I swear, this effect is so bizarre :)  Love the tiny people.', '2018-04-25 10:55:20.000000', NULL, 1),
(7566973, 1214186, 96751, '<td valign="top">Very artistic and beautiful.  I like the artistic application of the tiltshift (and tilt) and not the traditional miniaturization.</td>', 'Very artistic and beautiful.  I like the artistic application of the tiltshift (and tilt) and not the traditional miniaturization.', '2018-04-25 10:56:19.000000', NULL, 1),
(7566974, 1214161, 96751, '<td valign="top">I had to really look at this - it first looked like the dashboard of your car.  Love the tiny trains, but I think having all the other cars lined up in front of it diminishes the impact.</td>', 'I had to really look at this - it first looked like the dashboard of your car.  Love the tiny trains, but I think having all the other cars lined up in front of it diminishes the impact.', '2018-04-25 10:57:16.000000', NULL, 1),
(7566975, 1214184, 96751, '<td valign="top">Don''t know why the boats don''t look as "tiny" as I imagine they should.  But a dreamy view.</td>', 'Don''t know why the boats don''t look as "tiny" as I imagine they should.  But a dreamy view.', '2018-04-25 10:58:21.000000', NULL, 1),
(7566976, 1214042, 96751, '<td valign="top">One of the British Pauls live here :)<br/> <br/>Classic miniaturization. Was this a drone shot? And if so, I''m guessing it was miniaturized in post...?<br/> <br/>PS - very envious of your digs.</td>', 'One of the British Pauls live here :) Classic miniaturization. Was this a drone shot? And if so, I''m guessing it was miniaturized in post...? PS - very envious of your digs.', '2018-04-25 11:00:14.000000', NULL, 1),
(7566977, 1213865, 96751, '<td valign="top">Brilliant. Loving the fog and narrow color range.<br/> <br/>Did you take this from the museum across the river?</td>', 'Brilliant. Loving the fog and narrow color range. Did you take this from the museum across the river?', '2018-04-25 11:01:24.000000', NULL, 1),
(7566978, 1213938, 96751, '<td valign="top">Soooo looks like a train kit :)</td>', 'Soooo looks like a train kit :)', '2018-04-25 11:01:38.000000', NULL, 1),
