(7566980, 1214172, 96751, '<td valign="top">Very interesting image. There''s a zoom motion blur to it</td>', 'Very interesting image. There''s a zoom motion blur to it', '2018-04-25 11:03:37.000000', NULL, 1),
(7566981, 1214095, 96751, '<td valign="top">Classic lensbaby. Love the sense of motion, but for me there''s something lacking in the content of the image. A lot of negative space that isn''t particularly interesting.</td>', 'Classic lensbaby. Love the sense of motion, but for me there''s something lacking in the content of the image. A lot of negative space that isn''t particularly interesting.', '2018-04-25 11:05:03.000000', NULL, 1),
